// LayerFromFile's typed attributes, generated by tools/node_attributes.py from node_definitions.usda: its
// inputs and properties, read by name, and its outputs, committed by name. Don't edit it: change the
// definition and run `uv run python tools/node_attributes.py render`.
#pragma once

#include <pxr/pxr.h>
#include <pxr/usd/sdf/layer.h>

#include <string>

#include "node_input_reader.h"
#include "node_roles.h"

namespace proscenium {

struct LayerFromFileInputs {
  static constexpr const char* kPath = "props:path";

  std::string path{};
};

inline LayerFromFileInputs ReadLayerFromFileInputs(const NodeInputReader& reader) {
  LayerFromFileInputs inputs;
  inputs.path = reader.Value<std::string>("props:path");
  return inputs;
}

// What the node outputs; an output left empty, such as a null layer, commits nothing.
struct LayerFromFileOutputs {
  static constexpr const char* kLayer = "outputs:layer";

  PXR_NS::SdfLayerHandle layer{};
};

inline ValueOutputs WriteLayerFromFileOutputs(const LayerFromFileOutputs& outputs) {
  ValueOutputs values;
  if (outputs.layer) {
    values[PXR_NS::TfToken("outputs:layer")] = PXR_NS::VtValue(outputs.layer);
  }
  return values;
}

}  // namespace proscenium
